function selectFinaleDifficulty(value){finaleDifficulty=['EXPERT','NIGHTMARE'].includes(value)?value:'NORMAL';return finaleDifficulty;}
function selectGodDifficulty(value){godDifficulty=['EXPERT','NIGHTMARE'].includes(value)?value:'NORMAL';return godDifficulty;}
function challengeDifficultyControl(id,selected,label){return `<div class="selectline challenge-difficulty"><label>難易度 <select id="${id}" aria-label="${label}"><option value="NORMAL" ${selected==='NORMAL'?'selected':''}>NORMAL</option><option value="EXPERT" ${selected==='EXPERT'?'selected':''}>EXPERT</option><option value="NIGHTMARE" ${selected==='NIGHTMARE'?'selected':''}>NIGHTMARE</option></select></label><span class="small">EXPERT：敵1.3 / 1.2 / 1.1倍　NIGHTMARE：1.6 / 1.4 / 1.2倍（HP / 攻撃 / 速度、勝利報酬量は共通）</span></div>`;}
function godDifficultyControl(a){return a.flags.ex?challengeDifficultyControl('godDifficulty',godDifficulty,'神域連戦の難易度'):'';}
function startGodFight(){if($('#godDifficulty'))selectGodDifficulty($('#godDifficulty').value);beginFight('god',{difficulty:godDifficulty});}
function finaleDifficultyControl(a){if(!a.flags.stella)return '';return `<section class="card finale-difficulty">${challengeDifficultyControl('finaleDifficulty',finaleDifficulty,'最終決戦の難易度')}</section>`;}
const FINAL_CHAPTERS=[
 {id:'ex',title:'EXカイザー戦',detail:'いれーなで挑む三形態の決戦。',gate:'stella',clear:'ex',condition:'第20階層突破後、「？？？？？」から境界を越える'},
 {id:'stella',title:'ステラ戦 ― 星の境界',detail:'不滅と再誕でEXカイザーに挑む。クリアで専用いれーなが解放。',gate:'stella',clear:'stellaClear',condition:'第20階層突破後、「？？？？？」から境界を越える'},
 {id:'final',title:'専用いれーな最終決戦',detail:'神化・堕天の力で、EXカイザーとの決着へ。',gate:'final',clear:'finalClear',condition:'ステラ戦クリアで専用いれーなを解放'}
];
function finaleView(a){const active=battle&&!battle.result,cleared=FINAL_CHAPTERS.filter(c=>a.flags[c.clear]).length;return `${heading('最終決戦','この戦いの中心に立つのは、EXカイザー。','THE FINAL CONFRONTATION')}<section class="finale-keyvisual"><img src="${FINALE_ART}" alt="いれーなとEXカイザーが、金色と紫の力をまとい対峙する"><div class="finale-keyvisual-copy"><span>THE FALLEN STAR</span><h2>その翼で、<br>境界を超えろ。</h2><p>IRENA × EX KAISER</p></div></section><section class="finale-journey"><div><span class="tag">FINAL BATTLE / ${cleared} CLEAR</span><h2>三つの視点、一つの決着。</h2><p>いれーなとステラ。それぞれの力でEXカイザーに挑む。</p></div>${a.flags.lv100&&!a.flags.warp?button('？？？？？ ― 境界を越える','warp','','primary'):!a.flags.stella?'<p class="finale-lock">通常カイザー第20階層を突破し、境界の向こうへ。</p>':''}${active?button('進行中の戦闘に戻る →','nav','battle','primary'):''}</section><div class="finale-path"><span class="${a.flags.lv100?'reached':''}">20階突破</span><i>→</i><span class="${a.flags.warp?'reached':''}">境界を越える</span><i>→</i><span class="${a.flags.stella?'reached':''}">EX・ステラ解放</span><i>→</i><span class="${a.flags.final?'reached':''}">専用いれーな</span></div>${finaleDifficultyControl(a)}<div class="finale-chapters">${FINAL_CHAPTERS.map((c,i)=>{const state=finalChapterStatus(a,c);return `<section class="card finale-chapter state-${state.toLowerCase()}" data-final-chapter="${c.id}"><div class="finale-chapter-head"><span class="finale-chapter-number">0${i+1}</span><span class="tag">${state}</span></div><h2>${c.title}</h2><p>${a.flags[c.gate]?c.detail:c.condition}</p><div class="finale-chapter-foot"><span>${['通常いれーな / 三形態','ステラ / 不滅と再誕','専用いれーな / 神化・堕天'][i]}</span>${button(active?'戦闘を再開 →':a.flags[c.gate]?'挑戦する →':'未解放',active?'nav':'fight',active?'battle':c.id,'primary',!active&&!a.flags[c.gate])}</div></section>`;}).join('')}</div>${loadoutRibbon(a)}<div class="row">${button('聖域に戻る','nav','home','ghost')}${button('通常カイザーへ','nav','battle','ghost')}</div>`;}
function loadoutRibbon(a){return `<section class="loadout-ribbon" aria-label="現在の装備"><div class="loadout-ribbon-heading"><span class="tag">CURRENT LOADOUT</span><strong>通常いれーなの装備</strong></div><div class="loadout-slots">${[0,1].map(i=>{const id=a.equipped[i];return `<button data-action="openupgrade" data-id="powers" class="loadout-slot"><small>${i===0?'権能1 · 破壊の権能に使用':'権能2 · パッシブ'}</small><strong>${id?esc(name(id)):'未装備'}</strong><span>${id?'Lv.'+(a.powers[id]||a.resonance[id]):'選択する'} ›</span></button>`;}).join('')}</div><button class="authority-slot-swap ghost" data-action="swapAuthoritySlots" ${a.equipped.length!==2||battle&&!battle.result?'disabled':''}><span aria-hidden="true">⇄</span><span>1枠目・2枠目を入れ替え</span></button>${battle&&!battle.result?'<p class="authority-swap-note">戦闘終了または撤退後に入れ替えできます</p>':''}<button class="loadout-marks" data-action="openupgrade" data-id="marks"><span>刻印 ${a.markEquip.length}/3</span><strong>${a.markEquip.length?a.markEquip.map(id=>esc(name(id))).join(' · '):'刻印を選ぶ'}</strong><b>›</b></button></section>`;}
function chooseEquipment(a,id,kind){const list=kind==='mark'?a.markEquip:a.equipped,owned=kind==='mark'?a.marks.includes(id):!!(a.powers[id]||a.resonance[id]);if(owned&&!list.includes(id)&&list.length>=(kind==='mark'?3:2)){modal('入れ替える装備を選択',`<p class="equipment-incoming"><small>新しく装備</small><strong>${esc(name(id))}</strong></p><p class="small">外す装備を選んでください。所持品は消費しません。</p><div class="equipment-replace-options">${list.map(old=>button(`<span>${esc(name(old))}</span><small>入れ替える →</small>`,'replaceEquipment',kind+':'+id+':'+old,'ghost')).join('')}</div>`);return;}const message=equip(a,id,kind);persist();render();toast(message);}

function enemyLabel(b){return !b.trial&&!b.campaign&&['ex','stella','final'].includes(b.mode)?'EXカイザー':b.enemy.name;}
function enemyImage(b){if(b.trial?.kind==='mirror')return b.trial.unsealed?MIRROR_ART.phase3:b.trial.awake?MIRROR_ART.phase2:MIRROR_ART.red;return b.trial?.kind==='guard-break'?RAID_ART.trial:['ex','stella','final'].includes(b.mode)?ENEMIES.ex:ENEMIES[b.mode];}
function homeHubCard(icon,title,kicker,text,tabId){return `<section class="card modecard hub-card"><div class="hub-card-head"><span class="feature-icon">${uiIcon(icon,27)}</span><div><div class="tag">${kicker}</div><h3>${title}</h3></div></div><p class="small">${text}</p>${button(`開く ${uiIcon('arrow',16)}`,'openupgrade',tabId,'ghost')}</section>`;}

function modeCard(icon,title,desc,mode,unlocked,condition){return `<section class="card modecard"><div class="mode-symbol">${icon}</div><div class="tag">${unlocked?'UNLOCKED':'SEALED'}</div><h3>${title}</h3><p class="small">${unlocked?desc:condition}</p>${button(unlocked?'挑戦する →':'未解放','fight',mode,unlocked?'ghost':'',!unlocked)}</section>`;}
const UPGRADE_SECTIONS=[['powers','権能','深淵・黒翼・堕天・断罪など','権能の入手・強化・装備','violet'],['marks','刻印','刻印の装備・強化・管理','既存の刻印機能','red'],['resonance','権能共鳴','権能を組み合わせた共鳴権能','共鳴権能の作成・強化','gold'],['training','才能＆技','ステータス・才能・技の育成','既存の才能・技の育成','blue']];
function upgradeHero(a,detail=false){return `<header class="upgrade-hero"><img class="upgrade-hero-art" src="${UPGRADE_HERO}" alt=""><div class="upgrade-hero-copy"><span class="upgrade-crest" aria-hidden="true">✧</span><div><h1>${detail?'権能強化':'強化'}</h1><small>POWER UP</small><p>${detail?'強化する権能を選択してください':'強化したい項目を選択してください'}</p></div></div><div class="upgrade-wallet">権能ポイント <strong>✦ ${n(a.p)} P</strong></div></header>`;}
function upgrade(a){const section=UPGRADE_SECTIONS.find(x=>x[0]===tab);return `<div class="upgrade-ui">${upgradeHero(a,tab==='powers')}${battle?.result?`<div class="after-battle-tools"><span>戦果を残したまま、次の準備を。</span><div>${button('戦果に戻る','nav','battle','ghost')}${button(battle.result==='win'&&battle.mode==='normal'&&battle.floor<main20Limit(a)?'次の階層へ →':'再挑戦 →','retry','','primary')}</div></div>`:''}${['overview','powers','marks'].includes(tab)?loadoutRibbon(a):''}${tab==='overview'?`<section class="upgrade-category-list" aria-label="強化カテゴリ">${UPGRADE_SECTIONS.map(([id,title,desc,more,tone])=>`<button class="upgrade-category tone-${tone}" data-action="tab" data-id="${id}"><img src="${UPGRADE_ICONS[id]}" alt="" class="upgrade-category-icon"><span class="upgrade-category-copy"><strong>${title}</strong><span>${desc}</span><small>${more}</small></span><span class="upgrade-category-chevron" aria-hidden="true">›</span></button>`).join('')}</section><div class="upgrade-info">${uiIcon('book',26)}<span><strong>強化について</strong><small>項目を選択すると、既存の育成メニューに進みます。</small></span></div>`:`<section class="upgrade-subpage" aria-label="${section?.[1]||'育成'}">${tab==='powers'?powersView(a):`<h2 class="upgrade-subtitle">${section?.[1]||'育成'}</h2>${tab==='marks'?marksView(a):tab==='resonance'?resonanceView(a):trainingView(a)}`}</section>`}</div>`;}
function powerStatus(a,p){
 const info=powerUpgradeInfo(a,p.id),selected=a.equipped.includes(p.id);
 const state=!info.lv?(p.id==='star'?'locked':'unowned'):info.max?'max':info.canUpgrade?'ready':'insufficient';
 const label={locked:'未解放',unowned:'未所持',max:'★ 最大レベル',ready:'↑ 強化可能',insufficient:'◇ 素材不足'}[state];
 return {...info,selected,state,label};
}
function powerDetails(a,p){
 const v=powerStatus(a,p),growth=lv=>Math.round((powerGrowth(lv)-1)*100),isStar=p.id==='star';
 const effect=lv=>`<p>${esc(p.effect)}</p>${!isStar?`<div class="detail-growth">育成補正：基礎HP・攻撃・防御・速度 <strong>＋${growth(lv)}%</strong></div>`:''}`;
 const next=v.max?'<p>★ 最大レベルに到達しています。</p>':!v.lv?`<p>${esc(a.route20===1&&p.id==='judge'?'第15階層撃破 / 120P':p.source)}</p><small>${isStar?`実績 ${a.achieved.length} / ${ACHIEVEMENTS.length}`:'入手するとLv.1の固有効果が有効になります。'}</small><h3 class="unlock-effect-title">${isStar?'解放時の効果 · Lv.5':'入手時の効果 · Lv.1'}</h3>${effect(isStar?5:1)}`:effect(v.lv+1);
 return `<div class="upgrade-detail-modal"><header class="power-detail-heading"><img ${p.id!=='star'?`data-authority-art="${p.id}"`: ''} src="${UPGRADE_ART[p.id]}" alt=""><div><strong>${p.name}</strong><span>${v.lv?'Lv.'+v.lv+' / 5':'未解放・未所持'}</span><span class="power-state-badge badge-${v.state}">${v.label}</span>${v.selected?'<span class="power-equipped-badge">✓ 装備中</span>':''}</div></header><section class="upgrade-detail-section"><h3>現在の効果${v.lv?' · Lv.'+v.lv:''}</h3>${v.lv?effect(v.lv):'<p>未所持のため、まだ効果は発動しません。</p>'}</section><section class="upgrade-detail-section next-effect"><h3>${v.max?'強化完了':v.lv?'次レベルの効果 · Lv.'+(v.lv+1):'解放・入手条件'}</h3>${next}</section><dl class="power-detail-materials"><div><dt>強化に必要な欠片</dt><dd>${v.max?'— 最大レベル':!v.lv?'— 入手後に強化':n(v.cost)+' 個'}</dd></div><div><dt>所持欠片</dt><dd>${isStar?'— 実績報酬':n(v.have)+' 個'}</dd></div>${v.lv&&!v.max?`<div class="material-balance"><dt>${v.canUpgrade?'強化できます':'不足している欠片'}</dt><dd>${v.canUpgrade?'↑ 強化可能':n(v.cost-v.have)+' 個'}</dd></div>`:''}</dl><p class="small">装備枠は2つ。入手・装備・強化は一覧から操作できます。${!isStar?'固有効果はLv.1から有効で、Lv.2〜5は基礎能力の育成補正が上昇します。':''}</p></div>`;
}
function powersView(a){if(a.divinity?.schema===1)return divinityPowersView(a,button);
 const ordered=['abyss','wing','fallen','king','judge','star'].map(id=>POWERS.find(p=>p.id===id));
 if(powerSort==='owned')ordered.sort((x,y)=>Number(!!a.powers[y.id])-Number(!!a.powers[x.id]));
 return `<div class="upgrade-powers-header"><h2>権能一覧</h2><button class="ghost" data-action="sortPowers" aria-label="権能一覧を並び替える">${powerSort==='owned'?'通常の順序':'所持優先に並び替え'}</button></div><div class="upgrade-power-grid">${ordered.map(p=>{
 const v=powerStatus(a,p),costText=!v.lv?(p.id==='star'?`実績 ${a.achieved.length}/${ACHIEVEMENTS.length}`:'入手 120 P'):v.max?'育成完了':`欠片 ${n(v.have)} / ${n(v.cost)}`;
 const action=v.lv?`${button(v.selected?'装備解除':'装備する','equipPower',p.id,'ghost equip-action')}${button(v.max?'MAX':'強化','upgradePower',p.id,'upgrade-action',!v.canUpgrade)}`:button(p.id==='star'?'解放条件':'120Pで入手',p.id==='star'?'powerDetails':'buyPower',p.id,'upgrade-action',p.id!=='star'&&a.p<120);
 return `<article class="upgrade-power-card state-${v.state} ${v.selected?'equipped':''}"><div class="upgrade-power-main"><img class="upgrade-power-art" ${p.id!=='star'?`data-authority-art="${p.id}"`: ''} src="${UPGRADE_ART[p.id]}" alt=""><div class="upgrade-power-identity"><h3>${p.name}</h3><p class="upgrade-power-level">${v.lv?'Lv.'+v.lv+' / 5':'未所持'}</p></div><button class="upgrade-power-detail" data-action="powerDetails" data-id="${p.id}" aria-label="${p.name}の詳細を見る">${uiIcon('search',19)}</button></div><div class="power-card-badges">${v.selected?'<span class="power-equipped-badge">✓ 装備中</span>':''}<span class="power-state-badge badge-${v.state}">${v.label}</span></div><div class="upgrade-power-meter" aria-label="強化レベル ${v.lv}/5"><span style="width:${v.lv*20}%"></span></div><div class="upgrade-power-cost">${costText}</div><div class="upgrade-power-actions">${action}</div></article>`;
 }).join('')}</div><div class="upgrade-info">${uiIcon('book',26)}<span><strong>権能の詳細</strong><small>虫眼鏡で現在・次レベルの効果と必要素材を比較できます。</small></span></div>`;
}
function marksView(a){return `<div class="notice">刻印は独立した3枠。所持 ${a.marks.length}/10・装備 ${a.markEquip.length}/3。権能連動型は対応する通常権能の装備が必要です。<br>旧刻印の所持・装備は引き継がれます。戦闘中の装備変更は次の戦闘から反映されます。</div><div class="grid">${MARKS.map(m=>`<section class="card power-card ${a.markEquip.includes(m.id)?'selected':''}" data-mark="${m.id}"><div class="row"><div class="emblem">${m.icon}</div><div><h3>${m.name}</h3><small>${a.markEquip.includes(m.id)?'装備中':a.marks.includes(m.id)?'所持':'未所持'}${m.power?' / '+(a.equipped.includes(m.power)?'対応権能を装備中':'対応権能が未装備'):''}</small></div></div><p>${m.effect}</p><div class="actions">${a.marks.includes(m.id)?button(a.markEquip.includes(m.id)?'装備解除':'装備する','equipMark',m.id,'primary'):button(`${m.cost}P で入手`,'buyMark',m.id,'',a.p<m.cost)}</div></section>`).join('')}</div>`;}
